def gen(rng):
    def build(k, leaves):
        n = (1 << k) - 1
        t = [0] * n
        first = (1 << (k - 1)) - 1
        for i, v in enumerate(leaves):
            t[first + i] = v
        for i in range(first - 1, -1, -1):
            t[i] = min(t[2 * i + 1], t[2 * i + 2])
        return str(n) + '\n' + ' '.join(map(str, t))

    def rand_leaves(k, hi):
        return rng.sample(range(1, hi + 1), 1 << (k - 1))

    tests = [build(2, [4, 7]), build(2, [7, 4]), build(3, [8, 3, 6, 5]), build(3, [1, 2, 3, 4]), build(3, [4, 3, 2, 1]),
             build(4, [20, 11, 15, 30, 9, 40, 12, 25])]
    for k in (2, 3, 3, 4, 4, 4, 5, 5):
        tests.append(build(k, rand_leaves(k, 99)))
    for k in (6, 8, 10, 12):
        tests.append(build(k, rand_leaves(k, 10**9)))
    k = 17
    tests.append(build(k, rand_leaves(k, 10**9)))
    tests.append(build(k, sorted(rand_leaves(k, 10**9))))
    tests.append(build(k, sorted(rand_leaves(k, 10**9), reverse=True)))
    lv = sorted(rand_leaves(k, 10**9))
    lv = lv[::2][::-1] + lv[1::2]
    tests.append(build(k, lv))
    return tests

